'use strict';
let geoMap=null,geoViewport=null,geoFilter='all';
const GEO_CATEGORIES=[['all','All locations'],['academic','Colleges'],['student','Hostels & campus life'],['food','Food & shops'],['discovery','Discovery'],['wellness','Sport & health'],['services','Services']];
function applyWorkstackMap(places){CAMPUS_SOURCES.workstack=['WorkStack · Stack X Everything ABUAD map','https://workstack.com.ng/maps'];const originals={...Object.fromEntries(places.map(p=>[p.id,p]))};const matching={'Pavilion':'sports','White Rock':'senate','TDC':'tdc','ABUAD Multi System Hospital':'hospital','Male Hall 1 (Jamaica)':'hostel','Caf 1':'cafe','Owolabi Hall/Mosque':'owolabi','Alfa Belgore Hall/Church':'alfa','ICT BUILDING':'hub','College Of Pharmacy':'pharmacy','College Of Social and Management Sciences (SMS)':'social','College Of Engineering':'engineering','College Of Law':'law','College Of Medicine and Health Sciences (MHS)':'medicine','College Of Sciences':'lecture','Planetarium':'planetarium'};
const cloneActions=(base,id)=>originals[base].actions.map(a=>[id+'_'+a[0],...a.slice(1,5),{...a[5]},a[6]]);
for(const point of WORKSTACK_MAP.locations){let id=matching[point.name],p=id?originals[id]:null;const name=point.name;let category='services',type='office',actions,desc='A mapped campus destination. Choose a fictional activity to explore its place in your campus story.';
if(/Hall [1-7]|Hostel|NFH|MMH|FMH/i.test(name)){category='student';type='hostel';desc='A residential landmark from your supplied map. Roommate conversations and a moment to recharge.';actions=cloneActions('hostel','map'+point.sourceId)}
else if(/Caf|Cook|Deli|Spices|Smoothie/i.test(name)){category='food';type='cafe';desc='A food stop from the supplied map. Meals, prices and rewards here are fictional game choices.';actions=cloneActions('cafe','map'+point.sourceId);if(/Smoothie/i.test(name))actions=[['smoothie_drink','Buy a fictional smoothie','🥤',1,600,{hunger:22,mood:10},'A cool smoothie brightened your game day.']]}
else if(/Mall/i.test(name)){category='food';type='office';actions=[['map'+point.sourceId+'_browse','Window-shop with a friend','▦',1,0,{mood:9,social:5,energy:-4},'You browsed the mall and caught up with a friend.'],['map'+point.sourceId+'_snack','Pick up a fictional snack','🥪',1,400,{hunger:22,mood:4},'A quick snack refuelled your game day.']]}
else if(/College|Clinical|Dentistry/i.test(name)){category='academic';type='college';actions=[['map'+point.sourceId+'_learn','Join a fictional learning session','✎',2,0,{knowledge:10,skills:5,energy:-13},'A fictional learning session gave you a fresh perspective.']]}
else if(/TDC|Pavilion|Hospital/i.test(name)){category='wellness';type='arena'}
else if(/Planetarium|ICT|Hanger/i.test(name)){category='discovery';type=/Planetarium/.test(name)?'dome':'ict';actions=[['map'+point.sourceId+'_discover','Explore an aviation topic','✧',2,0,{knowledge:9,skills:5,energy:-10},'You learned about aviation in a fictional campus session.']]}
else if(/White Rock|Owolabi|Alfa|Church|Monastry/i.test(name)){category='student';type=/White/.test(name)?'senate':'hall';actions=[['map'+point.sourceId+'_reflect','Take a quiet reflection break','☁',1,0,{mood:13,energy:5},'A quiet moment helped you reset.']]}
if(!p){id='map'+point.sourceId;if(!actions){if(/Bank/.test(name))actions=[['map'+point.sourceId+'_budget','Review your student budget','₦',1,0,{skills:5,mood:5},'You made a fictional budget for your remaining game days.']];else if(/Fire/.test(name))actions=[['map'+point.sourceId+'_safety','Learn about campus fire safety','✧',1,0,{knowledge:6,skills:4,energy:-4},'You completed a fictional campus-safety learning activity.']];else if(/Pharmacy/.test(name))actions=[['map'+point.sourceId+'_awareness','Learn about medicine safety','✚',1,0,{knowledge:6,mood:4,energy:-4},'A fictional awareness activity expanded your understanding.']];else actions=[['map'+point.sourceId+'_visit','Explore this campus landmark','⌕',1,0,{mood:8,knowledge:3,energy:-5},'You explored '+name+' in your campus story.']]}
p={id,name,short:name,zone:['academic','student','discovery','wellness'].includes(category)?category:'student',type,icon:'📍',actions,desc};places.push(p)}
Object.assign(p,{name:point.name,short:point.name,sourceName:point.name,sourceId:point.sourceId,lat:point.lat,lng:point.lng,source:'workstack',photo:point.photo,category,mapped:true,fact:point.description||'Named location and marker position provided by the community-created map linked on WorkStack.'});
}
for(const p of places)if(!p.mapped){p.category=p.zone;p.mapped=false;p.photo=null}
}
function disposeGeoMap(){if(geoMap){const c=geoMap.getCenter();geoViewport={lat:c.lat,lng:c.lng,zoom:geoMap.getZoom()};geoMap.remove();geoMap=null}}
function mapPin(p){const active=selected===p.id,here=state.location===p.id;return `<span class="geo-pin ${active?'selected':''} ${here?'here':''}">${here?state.avatar:p.sourceId}</span>`}
function mountGeoMap(){if(typeof L==='undefined'){const box=$('#geoMap');if(box)box.innerHTML='<p class="empty">The interactive map could not load. Use the Original map tab or the directory below.</p>';return}const mapped=places.filter(p=>p.mapped);geoMap=L.map('geoMap',{scrollWheelZoom:false,maxZoom:19,minZoom:14,zoomControl:true});L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>'}).addTo(geoMap);if(geoViewport)geoMap.setView([geoViewport.lat,geoViewport.lng],geoViewport.zoom);else geoMap.fitBounds(mapped.map(p=>[p.lat,p.lng]),{padding:[25,25]});
const visible=mapped.filter(p=>geoFilter==='all'||p.category===geoFilter);for(const p of visible){const marker=L.marker([p.lat,p.lng],{icon:L.divIcon({className:'geo-marker',html:mapPin(p),iconSize:[32,38],iconAnchor:[16,36]}),title:p.name,alt:p.name,keyboard:true,zIndexOffset:state.location===p.id?1000:selected===p.id?500:0}).addTo(geoMap);marker.bindTooltip(escapeHtml(p.name),{direction:'top',offset:[0,-27],permanent:selected===p.id});marker.on('click',()=>selectPlace(p.id));}
L.control.scale({imperial:false,position:'bottomleft'}).addTo(geoMap);geoMap.on('tileerror',()=>{});
}
function selectPlace(id){const p=places.find(p=>p.id===id);if(!p)return;selected=id;zone=p.zone;render();ping();if(innerWidth<900)$('#locationPanel').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
function focusGeoPlace(id){const p=places.find(p=>p.id===id);if(!p||!p.mapped){toast('This destination has no position in the supplied map.');return}geoViewport={lat:p.lat,lng:p.lng,zoom:18};geoFilter='all';campusView='map';disposeGeoMap();geoViewport={lat:p.lat,lng:p.lng,zoom:18};selected=p.id;render()}
function geoDirectoryCards(list){if(!list.length)return '<p class="empty">No matches. Try Jamaica, White Rock, Caf, or a college name.</p>';return list.map(p=>`<button class="directory-place ${selected===p.id?'chosen':''}" data-place="${p.id}"><span class="directory-number">${p.mapped?p.sourceId:'◇'}</span><span><small>${p.mapped?'WORKSTACK MAP · '+(GEO_CATEGORIES.find(c=>c[0]===p.category)||['','Campus'])[1]:'EXISTING EXTRA · POSITION NOT PROVIDED'}</small><b>${escapeHtml(p.name)}</b><em>${state.location===p.id?'● You are here':state.visits.includes(p.id)?'✓ Explored':p.actions.length+' game activities'} ↗</em></span></button>`).join('')}
function geoSearchResults(){return places.filter(p=>(geoFilter==='all'||p.category===geoFilter)&&(p.name+' '+p.fact).toLowerCase().includes(campusQuery.toLowerCase()))}
function renderCampus(el){disposeGeoMap();const current=places.find(p=>p.id===state.location),mapped=places.filter(p=>p.mapped),explored=mapped.filter(p=>state.visits.includes(p.id)).length;el.innerHTML=`<div class="campus-overview"><div><span class="eyebrow">THE WORKSTACK MAP EDITION</span><h2>Your campus. The real coordinates.</h2><p>${mapped.length} mapped landmarks · source marker positions preserved</p></div><button class="where-am-i" id="locateMe">● ${escapeHtml(current.short)} ↗</button></div><div class="geo-source-banner"><span>📍</span><p>Based on the map you shared on <a href="https://workstack.com.ng/maps" target="_blank" rel="noopener noreferrer">WorkStack ↗</a><small>Community-created location data, not a surveyed building model.</small></p><button id="geoAbout" aria-label="Map accuracy details">ⓘ</button></div><div class="campus-toolbar"><div class="view-switch" role="group" aria-label="Campus display"><button id="mapView" class="${campusView==='map'?'chosen':''}" aria-pressed="${campusView==='map'}">⌘ Game map</button><button id="sourceView" class="${campusView==='source'?'chosen':''}" aria-pressed="${campusView==='source'}">↗ Original map</button><button id="listView" class="${campusView==='directory'?'chosen':''}" aria-pressed="${campusView==='directory'}">▦ Places</button></div><span class="explored-count">${explored} / 53 visited</span></div><div class="geo-filters" role="group" aria-label="Location categories">${GEO_CATEGORIES.map(([id,name])=>`<button data-filter="${id}" class="${geoFilter===id?'active':''}" aria-pressed="${geoFilter===id}">${name}</button>`).join('')}</div>${campusView==='map'?`<div class="geo-map-card"><div id="geoMap" class="geo-map" role="region" aria-label="ABUAD campus game map using WorkStack marker coordinates"></div><div class="geo-map-footer"><span>Numbered pins match the directory. Select a pin to play.</span><button id="fitCampus">Fit campus ↺</button></div></div><div class="geo-map-note">Coordinates: Stack X Everything ABUAD / WorkStack · basemap: OpenStreetMap. Basemap buildings and roads may differ from Google’s map. <button id="compareMap">Compare with the original →</button></div>`:campusView==='source'?`<div class="source-map-wrap"><iframe id="sourceMap" title="Original Stack X Everything ABUAD campus map linked by WorkStack" src="${WORKSTACK_MAP.sourceEmbed}" allowfullscreen loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe></div><div class="geo-map-note">This is the original embedded Google My Map. Its own controls and attribution are preserved. Select a destination below to continue the game.</div>`:''}<div class="campus-directory geo-directory"><div class="geo-directory-heading"><label for="campusSearch">Find your next stop</label><span>53 source markers + ${places.length-53} unplaced extras</span></div><input id="campusSearch" type="search" value="${escapeHtml(campusQuery)}" placeholder="Search Jamaica, White Rock, Caf 1, Bahamas…" autocomplete="off"><div class="directory-grid" id="directoryResults">${geoDirectoryCards(geoSearchResults())}</div></div><div class="campus-footnote">The 53 marker names and coordinates are retained from the supplied map. Building footprints, dimensions and 3D models were not provided. Travel, activities, prices and rewards are fictional game mechanics.</div>`;
$('#mapView').onclick=()=>{campusView='map';render()};$('#sourceView').onclick=()=>{campusView='source';render()};$('#listView').onclick=()=>{campusView='directory';render()};$('#locateMe').onclick=()=>focusGeoPlace(state.location);$('#geoAbout').onclick=aboutGeoMap;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{geoFilter=b.dataset.filter;render()});bindPlaces();$('#campusSearch').oninput=e=>{campusQuery=e.target.value;$('#directoryResults').innerHTML=geoDirectoryCards(geoSearchResults());bindPlaces()};if(campusView==='map'){mountGeoMap();$('#fitCampus').onclick=()=>{if(geoMap)geoMap.fitBounds(mapped.map(p=>[p.lat,p.lng]),{padding:[25,25]})};$('#compareMap').onclick=()=>{campusView='source';render()}}
}
function aboutGeoMap(){show(`<div class="eyebrow">WHAT MATCHES YOUR MAP</div><h2>Real pins.<br>Clear limits.</h2><p>All 53 location names and their latitude/longitude values come from the public export of <strong>Stack X Everything ABUAD: Campus Map</strong>, embedded by WorkStack. Source spelling is retained, including hostel and cafeteria labels.</p><p>The Original map tab embeds that Google My Map directly. The Game map places the same coordinates on OpenStreetMap; roads and building coverage can differ between providers.</p><p>The export contains point markers only: no building footprints, floor plans, heights, walking routes or 3D meshes. Six markers include source-linked photographs, shown where available. An exact architectural replica needs additional plans, measurements and reference photographs.</p><p>Five locations from the earlier edition remain as unplaced game extras. Their positions are not guessed. Nothing here uses your device’s location.</p><a href="https://workstack.com.ng/maps" target="_blank" rel="noopener noreferrer">View the supplied WorkStack map ↗</a><button class="primary" id="closeGeoAbout">Back to my campus</button>`);$('#closeGeoAbout').onclick=close}
function renderGeoLocation(){const p=places.find(p=>p.id===selected),here=state.location===p.id,source=CAMPUS_SOURCES[p.source];const photo=p.photo&&p.photo.startsWith('https://mymaps.usercontent.google.com/')?p.photo:null;$('#locationPanel').innerHTML=`${photo?`<figure class="source-building-photo"><img id="buildingPhoto" src="${escapeHtml(photo)}" alt="Source map reference photograph for ${escapeHtml(p.name)}" loading="lazy" referrerpolicy="no-referrer"><figcaption>Reference photo from the supplied map · <a href="${WORKSTACK_MAP.sourceEmbed}" target="_blank" rel="noopener">view source ↗</a></figcaption></figure>`:`<div class="geo-location-badge"><span>${p.mapped?'📍 '+p.sourceId:'◇'}</span><div>${p.mapped?'SOURCE MAP LANDMARK':'UNPLACED GAME EXTRA'}<small>${here?'● You are here':p.mapped?'Select your next move':'Coordinates not provided'}</small></div></div>`}<div class="location-title"><span>${p.mapped?'SOURCE NAME & POSITION PRESERVED':'EXTRA FROM THE EARLIER EDITION'}</span><h2>${escapeHtml(p.name)}</h2><p>${escapeHtml(p.desc)}</p></div>${p.mapped?`<div class="coordinate-card"><span>${p.lat.toFixed(7)}° N · ${p.lng.toFixed(7)}° E</span><button id="showOnMap">Show pin ↗</button></div>`:''}<div class="campus-fact">${escapeHtml(p.fact)}<a href="${source[1]}" target="_blank" rel="noopener noreferrer">${p.mapped?'WorkStack map source':'University source'} ↗</a></div>${!here&&!state.finished?(typeof routineTravelContent==='function'?routineTravelContent(p):`<div class="travel-box"><b>Travel here to start an activity.</b><div><button class="secondary" id="travelWalk">Walk · 1 game hr · −5 energy</button><button class="secondary" id="travelShuttle">Shuttle · 1 game hr · ₦150</button></div><small>These are fictional game costs, not real routes, fares or travel estimates.</small></div>`):''}${p.actions.map(a=>`<button class="action" data-action="${a[0]}" ${state.finished||!here?'disabled':''}><span class="action-icon">${a[2]}</span><span><b>${a[5].attendance&&typeof routineClass==='function'?'Attend scheduled course · 08:30':escapeHtml(a[1])}</b><small>${a[5].attendance&&typeof routineClass==='function'?'UNTIL 10:00':a[3]+' HR'} · ${a[4]?money(a[4]):a[5].money?'EARN '+money(a[5].money):'FREE'}${a[5].energy<0?' · '+a[5].energy+' ENERGY':''}</small></span><span>↗</span></button>`).join('')}<small class="game-fiction">Play a fictional campus story. Source marker positions do not define exact building shapes or access permissions.</small>`;document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));if(typeof bindRoutineTravel==='function')bindRoutineTravel();if($('#travelWalk'))$('#travelWalk').onclick=()=>travel('walk');if($('#travelShuttle'))$('#travelShuttle').onclick=()=>travel('shuttle');if(p.mapped)$('#showOnMap').onclick=()=>focusGeoPlace(p.id);if(photo)$('#buildingPhoto').onerror=()=>{$('#buildingPhoto').replaceWith(document.createTextNode('The reference photo is unavailable. Use the source map link below.'))}}
